const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon([[
    [-84.0, 28.0],
    [-84.0, 25.0],
    [-82.0, 25.0],
    [-82.0, 28.0]
  ]]);

  const date1 = '2004-10-30';
  const date2 = '2004-11-21';
  const collectionName = 'NASA/GSFC/OBPG/MODIS/AQUA/L3SMI';
  const bandName = 'chlor_a';

  // Function to get mean chlorophyll and pixel count for a given date
  const getChlorophyllInfo = (dateString) => {
    const imageCollection = ee.ImageCollection(collectionName)
      .filterDate(dateString, ee.Date(dateString).advance(1, 'day'))
      .select(bandName);

    const size = imageCollection.size().getInfo();
    if (size === 0) {
      return { 'size': 0 };
    }

    const image = imageCollection.first();
    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 4000, // Use a coarse scale for this L3 product to avoid timeout
      maxPixels: 1e9
    });

    return {
      'size': size,
      'mean': stats.get(bandName + '_mean').getInfo(),
      'count': stats.get(bandName + '_count').getInfo()
    };
  };

  // 2. Data Acquisition & Check
  const info_oct = getChlorophyllInfo(date1);
  const info_nov = getChlorophyllInfo(date2);

  if (info_oct.size === 0 || info_nov.size === 0) {
    console.log(`Image collection size for ${date1}: ${info_oct.size}`);
    console.log(`Image collection size for ${date2}: ${info_nov.size}`);
    console.log('Evidence: No image found for one or both dates.');
    console.log('A'); // C1
    return;
  }

  // 3. Processing & Pixel Validation
  if (!info_oct.count || info_oct.count === 0 || !info_nov.count || info_nov.count === 0) {
    console.log(`Valid pixels for ${date1}: ${info_oct.count || 0}`);
    console.log(`Valid pixels for ${date2}: ${info_nov.count || 0}`);
    console.log('Evidence: No valid pixels in the region of interest for one or both dates.');
    console.log('C2');
    return;
  }

  // 4. Calculation & Validation
  const mean_oct = info_oct.mean;
  const mean_nov = info_nov.mean;

  if (mean_oct === null || mean_nov === null || typeof mean_oct === 'undefined' || typeof mean_nov === 'undefined') {
      console.log(`Mean value for ${date1}: ${mean_oct}`);
      console.log(`Mean value for ${date2}: ${mean_nov}`);
      console.log('Evidence: Calculation returned a null value.');
      console.log('C3');
      return;
  }

  // 5. Final Answer
  console.log(`Oct 30, 2004 Mean Chlorophyll: ${mean_oct.toFixed(3)} mg/m^3`);
  console.log(`Oct 30, 2004 Valid Pixels: ${info_oct.count}`);
  console.log(`Nov 21, 2004 Mean Chlorophyll: ${mean_nov.toFixed(3)} mg/m^3`);
  console.log(`Nov 21, 2004 Valid Pixels: ${info_nov.count}`);

  if (mean_nov > mean_oct) {
    console.log('Evidence: Chlorophyll concentration was higher on November 21, 2004.');
    console.log('A');
  } else {
    console.log('Evidence: Chlorophyll concentration was not higher on November 21, 2004.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred: ', err);
    console.log('D');
});
